import{_ as o,o as t,c as n,a2 as i}from"./chunks/framework.BXA5Pi9t.js";const m=JSON.parse('{"title":"One Port, Many Gateways- Scaling RGW for Uptime & Production Resilience - Jack Shen, Bloomberg LP","description":"","frontmatter":{"title":"One Port, Many Gateways- Scaling RGW for Uptime & Production Resilience - Jack Shen, Bloomberg LP","date":"2025-11-19T00:00:00.000Z","updated":"2025-11-20T00:00:00.000Z","tags":["Ceph","RGW","High Availability","Scalability","Storage Optimization"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2025/One_Port_Many_Gateways_-_Scaling_RGW_for_Uptime_Production_Resilience_-_Jack_Shen_Bloomberg_LP.md","filePath":"posts/2025/One_Port_Many_Gateways_-_Scaling_RGW_for_Uptime_Production_Resilience_-_Jack_Shen_Bloomberg_LP.md","lastUpdated":1780459816000}'),r={name:"posts/2025/One_Port_Many_Gateways_-_Scaling_RGW_for_Uptime_Production_Resilience_-_Jack_Shen_Bloomberg_LP.md"};function _(l,e,s,a,g,p){return t(),n("div",null,[...e[0]||(e[0]=[i("<p>Bloomberg的存储工程负责人Jack Shen在Ceph社区会议上分享了Bloomberg如何通过Ceph RGW实现零停机重启的方案。</p><p><strong>会议要点</strong>：</p><ul><li><strong>Bloomberg业务背景</strong>：Bloomberg是一家金融科技公司，其核心业务依赖于处理海量金融数据，并采用混合存储架构，其中Ceph作为核心存储技术，对高可用性要求极高。</li><li><strong>当前RGW重启痛点</strong>：传统的滚动重启方式在Bloomberg的生产环境中需要4小时才能完成，导致客户端遭遇500错误和延迟，操作复杂且无法满足金融监管要求的快速补丁部署。</li><li><strong>解决方案</strong>： <ul><li>利用Linux Kernel的SO_REUSEPORT特性，允许多个进程绑定相同端口，内核充当简易负载均衡器。</li><li>修改Ceph代码，使RGW支持端口重用标志。</li><li>系统架构变化，实现新旧实例同时运行，旧实例处理现有请求，新实例处理新请求。</li></ul></li><li><strong>实施细节</strong>：包括配置变更、systemd调整、自动化脚本等。</li><li><strong>收益验证</strong>：错误率降低500倍，重启窗口从4小时缩短至接近零，扩展性提升。</li><li><strong>最佳实践参数</strong>：包括graceful_shutdown_timeout和systemd TimeoutStopSec的计算公式。</li><li><strong>问答环节要点</strong>：包括监控策略、异常处理等。</li><li><strong>行动计划</strong>：社区采纳、Backport建议、操作手册等。</li><li><strong>专业术语保留</strong>：RGW、SO_REUSEPORT、inflight request、rolling restart、LB、SLO、tick data、draining状态等。</li></ul><p><strong>改进后的总结</strong>：</p><p>Bloomberg通过利用Linux Kernel的SO_REUSEPORT特性和修改Ceph代码，实现了Ceph RGW的零停机重启。该方案显著降低了重启时间，提高了系统的可用性和扩展性，对于需要高可用性的存储环境具有参考价值。</p><p><strong>可能的错误、误解或遗漏</strong>：</p><ul><li>原始总结中未提及Bloomberg如何处理自动化过程中的异常情况。</li><li>原始总结中未详细说明如何实现新旧实例同时运行的具体技术细节。</li></ul><p><strong>改进后的总结内容</strong>：</p><p>Bloomberg的存储工程负责人Jack Shen在Ceph社区会议上分享了Bloomberg如何通过Ceph RGW实现零停机重启的方案。该方案利用Linux Kernel的SO_REUSEPORT特性和修改Ceph代码，实现了新旧实例同时运行，显著降低了重启时间，提高了系统的可用性和扩展性。方案包括配置变更、systemd调整、自动化脚本等实施细节，适用于需要高可用性的存储环境。</p>",9)])])}const S=o(r,[["render",_]]);export{m as __pageData,S as default};
